// New macOS credential vault. It reproduces the BEHAVIOR of Xshell's Master Password mode seen in
// nssecurity.dll strings (enable/set/change/remove a master password, 6-50 characters, all session
// passwords encrypted under it, no recovery if forgotten), NOT its algorithm or on-disk .mpw format.
// Xshell's actual encryption was not analyzed and this does not read or decrypt Xshell's files.
// Crypto is standard and modern: PBKDF2-HMAC-SHA256 to derive a key from the master password, then
// AES-GCM for each stored secret. On a real build the macOS app may instead keep this key in the
// Keychain; that is a deployment choice above this module.

public enum VaultError: Error, Equatable {
    case passwordLength            // Xshell: "Please input password 6 ~ 50 characters."
    case locked
    case wrongPassword             // Xshell: "Make sure that the password you have typed is correct."
    case notFound(String)
    case corruptVault(String)
    case alreadyExists(String)
}

public enum MasterPasswordPolicy {
    public static let minLength = 6
    public static let maxLength = 50
    public static func validate(_ password: String) throws {
        let n = password.count
        guard n >= minLength && n <= maxLength else { throw VaultError.passwordLength }
    }
}

/// PBKDF2-HMAC-SHA256. Implemented over CryptoKit's HMAC so the module needs no CommonCrypto import.
enum PBKDF2 {
    static func deriveKey(password: [UInt8], salt: [UInt8], iterations: Int, keyBytes: Int = 32) -> [UInt8] {
        precondition(iterations > 0 && keyBytes > 0)
        let key = SymmetricKey(data: password)
        let hLen = SHA256.byteCount
        let blocks = (keyBytes + hLen - 1) / hLen
        var output: [UInt8] = []
        output.reserveCapacity(blocks * hLen)
        for block in 1...blocks {
            var inti = salt
            let b = UInt32(block)
            inti.append(contentsOf: [UInt8(b >> 24 & 0xFF), UInt8(b >> 16 & 0xFF), UInt8(b >> 8 & 0xFF), UInt8(b & 0xFF)])
            var u = Array(HMAC<SHA256>.authenticationCode(for: inti, using: key))
            var t = u
            if iterations > 1 {
                for _ in 1..<iterations {
                    u = Array(HMAC<SHA256>.authenticationCode(for: u, using: key))
                    for i in 0..<t.count { t[i] ^= u[i] }
                }
            }
            output.append(contentsOf: t)
        }
        return Array(output.prefix(keyBytes))
    }
}

/// The vault's serialized form. Field order is fixed so JSON encodes deterministically.
public struct VaultFile: Codable, Equatable {
    public var version = 1
    public var iterations: Int
    public var saltBase64: String
    /// AES-GCM sealing of a fixed token, used only to check the password on unlock.
    public var verifierBase64: String
    /// id -> base64(AES-GCM combined box) of the stored secret.
    public var entries: [String: String]
}

public final class MasterVault {
    public static let defaultIterations = 210_000
    private static let verifierToken = Array("carve-master-vault/v1".utf8)

    private let file: VaultFile
    private let key: SymmetricKey?   // non-nil only while unlocked
    public var isLocked: Bool { key == nil }
    public var identifiers: [String] { file.entries.keys.sorted() }

    private init(file: VaultFile, key: SymmetricKey?) { self.file = file; self.key = key }

    /// Creates a new, unlocked vault with no entries.
    public static func create(password: String, iterations: Int = defaultIterations) throws -> MasterVault {
        try MasterPasswordPolicy.validate(password)
        var salt = [UInt8](repeating: 0, count: 16)
        for i in salt.indices { salt[i] = UInt8.random(in: .min ... .max) }
        let key = SymmetricKey(data: PBKDF2.deriveKey(password: Array(password.utf8), salt: salt, iterations: iterations))
        let sealed = try AES.GCM.seal(verifierToken, using: key)
        let file = VaultFile(iterations: iterations, saltBase64: Data(salt).base64EncodedString(),
                             verifierBase64: sealed.combined!.base64EncodedString(), entries: [:])
        return MasterVault(file: file, key: key)
    }

    /// Loads a serialized vault in the locked state.
    public static func load(_ data: Data) throws -> MasterVault {
        guard let file = try? JSONDecoder().decode(VaultFile.self, from: data) else { throw VaultError.corruptVault("not a vault file") }
        guard file.version == 1 else { throw VaultError.corruptVault("unsupported version \(file.version)") }
        guard (1...2_000_000).contains(file.iterations) else { throw VaultError.corruptVault("invalid PBKDF2 iteration count") }
        guard Data(base64Encoded: file.saltBase64) != nil, Data(base64Encoded: file.verifierBase64) != nil else { throw VaultError.corruptVault("bad base64") }
        return MasterVault(file: file, key: nil)
    }

    public func serialized() throws -> Data {
        let encoder = JSONEncoder(); encoder.outputFormatting = [.sortedKeys]
        return try encoder.encode(file)
    }

    /// Returns an unlocked copy, or throws wrongPassword. Constant work regardless of outcome (PBKDF2 then one GCM open).
    public func unlocked(password: String) throws -> MasterVault {
        guard let salt = Data(base64Encoded: file.saltBase64), let verifier = Data(base64Encoded: file.verifierBase64) else { throw VaultError.corruptVault("bad base64") }
        let key = SymmetricKey(data: PBKDF2.deriveKey(password: Array(password.utf8), salt: Array(salt), iterations: file.iterations))
        do {
            let box = try AES.GCM.SealedBox(combined: verifier)
            let opened = try AES.GCM.open(box, using: key)
            guard Array(opened) == Self.verifierToken else { throw VaultError.wrongPassword }
        } catch is CryptoKitError { throw VaultError.wrongPassword }
        return MasterVault(file: file, key: key)
    }

    public func locked() -> MasterVault { MasterVault(file: file, key: nil) }

    private func requireKey() throws -> SymmetricKey { guard let key else { throw VaultError.locked }; return key }

    /// Stores (or, with overwrite, replaces) a secret. Returns a new vault; the receiver is unchanged.
    public func storing(id: String, secret: String, overwrite: Bool = false) throws -> MasterVault {
        let key = try requireKey()
        if file.entries[id] != nil && !overwrite { throw VaultError.alreadyExists(id) }
        let sealed = try AES.GCM.seal(Array(secret.utf8), using: key)
        var next = file; next.entries[id] = sealed.combined!.base64EncodedString()
        return MasterVault(file: next, key: key)
    }

    public func retrieve(id: String) throws -> String {
        let key = try requireKey()
        guard let b64 = file.entries[id], let combined = Data(base64Encoded: b64) else { throw VaultError.notFound(id) }
        do {
            let opened = try AES.GCM.open(try AES.GCM.SealedBox(combined: combined), using: key)
            return String(decoding: opened, as: UTF8.self)
        } catch is CryptoKitError { throw VaultError.corruptVault(id) }
    }

    public func removing(id: String) throws -> MasterVault {
        _ = try requireKey()
        guard file.entries[id] != nil else { throw VaultError.notFound(id) }
        var next = file; next.entries[id] = nil
        return MasterVault(file: next, key: key)
    }

    /// Re-encrypts every entry under a new master password. Requires the vault to be unlocked.
    public func changingPassword(to newPassword: String, iterations: Int = defaultIterations) throws -> MasterVault {
        let key = try requireKey()
        try MasterPasswordPolicy.validate(newPassword)
        var fresh = try MasterVault.create(password: newPassword, iterations: iterations)
        for id in identifiers {
            let secret = try retrieve(id: id)   // decrypt with current key
            fresh = try fresh.storing(id: id, secret: secret)
        }
        _ = key
        return fresh
    }

    /// Xshell semantics: removing the master password discards the encrypted session passwords, which cannot be recovered.
    public static func removedVault() -> VaultRemoval { VaultRemoval() }
    public struct VaultRemoval: Equatable { public let discardedSecrets = true }
}

// Feature entry: payload is JSON {"op": "...", ...}. State is a serialized vault passed in and out as
// base64 under "vault"; this keeps the feature stateless per the plan contract.
public enum MasterPasswordFeature: CarveFeature {
    public static let id = "master-password"
    public static let contractSha256 = "32e908cfddce634f246928838ba4ca6831cd2a3b97e05d91ec1f68f79a551de2"
    public static let dependsOn: [String] = ["profiles"]

    public static func run(_ request: FeatureRequest, dependencies: FeatureOutputs) throws -> FeatureResponse {
        if request.payload.isEmpty {
            return FeatureResponse(payload: #"{"ready":true,"minLength":6,"maxLength":50,"kdf":"PBKDF2-HMAC-SHA256","cipher":"AES-GCM"}"#)
        }
        guard let obj = try JSONSerialization.jsonObject(with: Data(request.payload.utf8)) as? [String: Any], let op = obj["op"] as? String else {
            throw FeatureError.failed(id, "expected JSON {op, ...}")
        }
        func vaultIn() throws -> MasterVault {
            guard let b64 = obj["vault"] as? String, let data = Data(base64Encoded: b64) else { throw FeatureError.failed(id, "missing vault") }
            return try MasterVault.load(data)
        }
        func out(_ vault: MasterVault, _ extra: [String: Any] = [:]) throws -> FeatureResponse {
            var o = extra
            o["vault"] = try vault.serialized().base64EncodedString()
            o["ids"] = vault.identifiers
            return FeatureResponse(payload: String(decoding: try JSONSerialization.data(withJSONObject: o, options: [.sortedKeys]), as: UTF8.self))
        }
        do {
            switch op {
            case "create":
                return try out(try MasterVault.create(password: obj["password"] as? String ?? ""))
            case "store":
                let v = try vaultIn().unlocked(password: obj["password"] as? String ?? "")
                return try out(try v.storing(id: obj["id"] as? String ?? "", secret: obj["secret"] as? String ?? "", overwrite: (obj["overwrite"] as? Bool) ?? false))
            case "retrieve":
                let v = try vaultIn().unlocked(password: obj["password"] as? String ?? "")
                return try out(v, ["secret": try v.retrieve(id: obj["id"] as? String ?? "")])
            default:
                throw FeatureError.failed(id, "unknown op \(op)")
            }
        } catch let e as VaultError {
            throw FeatureError.failed(id, "\(e)")
        }
    }
}
